-- Disposable database only: minimal Supabase schema used by the privilege tests.
CREATE ROLE authenticated;
CREATE ROLE anon;
CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA talent;
SET search_path = talent;
CREATE SCHEMA auth;
CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA talent,auth,storage TO authenticated,service_role,anon;
CREATE TABLE talent.workspace (id bigint PRIMARY KEY, workspace_admins uuid[] NOT NULL, workspace_name text);
CREATE TABLE talent.profiles (id uuid PRIMARY KEY, user_id uuid, workspace_id bigint REFERENCES workspace(id), first_name text);
CREATE TABLE talent.positions (id uuid PRIMARY KEY, workspace_id bigint REFERENCES workspace(id), name text, access_restricted boolean DEFAULT false);
CREATE TABLE talent.candidates (id uuid PRIMARY KEY, workspace_id bigint REFERENCES workspace(id), position_id uuid REFERENCES positions(id) ON DELETE SET NULL, first_name text);
CREATE TABLE talent.interviews (id uuid PRIMARY KEY, candidate_id uuid REFERENCES candidates(id), interviewer_id uuid, status text, interview_date timestamptz);
CREATE TABLE talent.candidate_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),candidate_id uuid REFERENCES candidates(id),author_id uuid REFERENCES profiles(id),content text);
CREATE TABLE talent.position_members (position_id uuid REFERENCES positions(id) ON DELETE CASCADE,profile_id uuid REFERENCES profiles(id),PRIMARY KEY(position_id,profile_id));
CREATE TABLE storage.buckets(id text PRIMARY KEY, public boolean);
INSERT INTO storage.buckets VALUES ('resumes',true);
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text,name text);
CREATE FUNCTION talent.current_workspace_id() RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=talent AS $$ SELECT workspace_id FROM profiles WHERE user_id=auth.uid() $$;
CREATE FUNCTION talent.is_workspace_admin(_workspace_id bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=talent AS $$ SELECT EXISTS (SELECT 1 FROM workspace WHERE id=_workspace_id AND auth.uid()=ANY(workspace_admins)) $$;
CREATE FUNCTION talent.guard_profile_workspace() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
CREATE TRIGGER profiles_guard_workspace BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION guard_profile_workspace();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['workspace','profiles','positions','candidates','interviews','candidate_comments','position_members'] LOOP EXECUTE format('ALTER TABLE talent.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON talent.%I TO authenticated',t); END LOOP; END $$;
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON storage.objects TO authenticated;
CREATE POLICY "Team can view profiles" ON profiles FOR SELECT TO authenticated USING (workspace_id=current_workspace_id());
CREATE POLICY own_profile_update ON profiles FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY workspace_read ON workspace FOR SELECT TO authenticated USING (id=current_workspace_id());
CREATE POLICY workspace_update ON workspace FOR UPDATE TO authenticated USING (is_workspace_admin(id));
-- Simulate the old broad policy: the migration must remove it.
CREATE POLICY "Team can manage candidates" ON candidates FOR ALL TO authenticated USING (workspace_id=current_workspace_id()) WITH CHECK (workspace_id=current_workspace_id());
